create or replace function public.app_admin_prontuario(p_token text,p_funcionario_id uuid) returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare v record; v_func jsonb; begin select * into v from public.app_tenant_usuario(p_token) limit 1; if v.perfil not in('admin','administrador','gestor') then return jsonb_build_object('sucesso',false,'erro','Acesso negado'); end if; select to_jsonb(f) into v_func from public.funcionarios f where f.id=p_funcionario_id and f.empresa_id=v.empresa_id limit 1; if v_func is null then return jsonb_build_object('sucesso',false,'erro','Funcionário não encontrado'); end if; return jsonb_build_object('sucesso',true,'funcionario',v_func,'documentos',coalesce((select jsonb_agg(to_jsonb(d) order by d.created_at desc) from public.funcionario_documentos d where d.funcionario_id=p_funcionario_id and d.empresa_id=v.empresa_id),'[]'::jsonb),'advertencias',coalesce((select jsonb_agg(to_jsonb(a) order by a.data_ocorrencia desc) from public.funcionario_advertencias a where a.funcionario_id=p_funcionario_id and a.empresa_id=v.empresa_id),'[]'::jsonb),'timeline',coalesce((select jsonb_agg(to_jsonb(t) order by t.data_evento desc,t.created_at desc) from public.funcionario_timeline t where t.funcionario_id=p_funcionario_id and t.empresa_id=v.empresa_id),'[]'::jsonb),'atestados',coalesce((select jsonb_agg(to_jsonb(a) order by a.created_at desc) from public.atestados a where a.funcionario_id=p_funcionario_id),'[]'::jsonb),'justificativas',coalesce((select jsonb_agg(to_jsonb(j) order by j.data_registro desc) from public.justificativas_ponto j where j.funcionario_id=p_funcionario_id),'[]'::jsonb),'ponto',coalesce((select jsonb_agg(to_jsonb(r) order by r.data desc) from (select * from public.registros_ponto where funcionario_id=p_funcionario_id order by data desc limit 180) r),'[]'::jsonb),'holerites',coalesce((select jsonb_agg(to_jsonb(h) order by h.ano desc,h.mes desc) from (select * from public.holerites where funcionario_id=p_funcionario_id and disponivel=true order by ano desc,mes desc limit 6) h),'[]'::jsonb),'ferias',coalesce((select jsonb_agg(to_jsonb(x) order by x.inicio desc) from public.rh_ferias x where x.funcionario_id=p_funcionario_id and x.empresa_id=v.empresa_id),'[]'::jsonb),'afastamentos',coalesce((select jsonb_agg(to_jsonb(x) order by x.inicio desc) from public.rh_afastamentos x where x.funcionario_id=p_funcionario_id and x.empresa_id=v.empresa_id),'[]'::jsonb)); end; $$;

create or replace function public.app_admin_criar_ordem(p_token text,p_numero text,p_descricao text,p_prioridade text,p_prazo date,p_quantidade integer,p_valor numeric,p_observacoes text default null) returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare v record; v_id uuid; begin select * into v from public.app_tenant_usuario(p_token) limit 1; if v.perfil not in('admin','administrador','gestor') then return jsonb_build_object('sucesso',false,'erro','Acesso negado'); end if; if trim(coalesce(p_numero,''))='' or trim(coalesce(p_descricao,''))='' then return jsonb_build_object('sucesso',false,'erro','Número e descrição são obrigatórios'); end if; insert into public.ordens_servico(empresa_id,numero,descricao,status,prioridade,data_entrada,prazo,quantidade,valor_total,observacoes,created_by) values(v.empresa_id,trim(p_numero),trim(p_descricao),'recebida',coalesce(nullif(p_prioridade,''),'normal'),current_date,p_prazo,greatest(coalesce(p_quantidade,1),1),coalesce(p_valor,0),p_observacoes,v.usuario_id) returning id into v_id; return jsonb_build_object('sucesso',true,'id',v_id); exception when unique_violation then return jsonb_build_object('sucesso',false,'erro','Número de ordem já cadastrado'); end; $$;
grant execute on function public.app_admin_prontuario(text,uuid) to anon,authenticated;
grant execute on function public.app_admin_criar_ordem(text,text,text,text,date,integer,numeric,text) to anon,authenticated;
